(() => {
 const H = window.Hou = {};
 H.e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={today:'<rect x="3" y="5" width="14" height="12" rx="2"/><path d="M6 3v4m8-4v4M3 9h14m-10 4h2"/>',library:'<path d="M3 4h5a3 3 0 0 1 3 3v10a4 4 0 0 0-3-1H3zm14 0h-3a3 3 0 0 0-3 3v10a4 4 0 0 1 3-1h3z"/>',record:'<path d="M5 3h8l3 3v11H5zM12 3v4h4M8 10h5m-5 3h5"/>',settings:'<path d="M4 5h12M4 10h12M4 15h12"/><circle cx="7" cy="5" r="2"/><circle cx="13" cy="10" r="2"/><circle cx="8" cy="15" r="2"/>',arrow:'<path d="M4 10h12m-5-5 5 5-5 5"/>',up:'<path d="M5 15 15 5M5 5h10v10"/>',back:'<path d="M16 10H4m5-5-5 5 5 5"/>',chevron:'<path d="m7 5 5 5-5 5"/>',plus:'<path d="M10 4v12M4 10h12"/>',clock:'<circle cx="10" cy="10" r="7"/><path d="M10 6v4l3 2"/>',bell:'<path d="M4 14h12l-2-3V8a4 4 0 0 0-8 0v3zm4 3h4"/>',sun:'<circle cx="10" cy="10" r="3"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M4 4l1 1m10 10 1 1M4 16l1-1M15 5l1-1"/>',moon:'<path d="M16 12a7 7 0 0 1-9-9 7 7 0 1 0 9 9Z"/>',close:'<path d="m5 5 10 10M5 15 15 5"/>',check:'<path d="m4 10 4 4 8-8"/>',doc:'<path d="M5 2h7l4 4v12H5zM12 2v5h4M8 11h5m-5 3h5"/>',upload:'<path d="M10 13V3M6 7l4-4 4 4M3 13v4h14v-4"/>',pause:'<path d="M7 4v12m6-12v12"/>',play:'<path d="m6 4 10 6-10 6z"/>',more:'<circle cx="4" cy="10" r=".7"/><circle cx="10" cy="10" r=".7"/><circle cx="16" cy="10" r=".7"/>',mark:'<path d="m4 13 8-9 4 4-8 9H4zm6-7 4 4M3 19h14"/>',note:'<path d="M4 3h12v11l-4 4H4zm7 15v-5h5M7 7h6M7 10h3"/>',info:'<circle cx="10" cy="10" r="7"/><path d="M10 9v5m0-8v1"/>',archive:'<path d="M3 3h14v4H3zm1 4v10h12V7M8 10h4"/>',repeat:'<path d="M16 7a6 6 0 0 0-10-3L3 7m0-4v4h4m-4 6a6 6 0 0 0 10 3l3-3m0 4v-4h-4"/>',key:'<circle cx="7" cy="8" r="4"/><path d="m10 11 6 6m-3-3 2-2m-4 0 2-2"/>'};
 H.icon=(name,extra='')=>`<svg class="od-icon icon ${extra}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.doc}</svg>`;
 const e=H.e, icon=H.icon;
 H.button=(label,action,cls='text-button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
 const b=H.button;
 H.book=id=>H.state.books.find(x=>x.id===id);
 // 归档读物的知识点是否继续出题，由设置中的"旧书复习"决定；暂停的读物一律不出题
 H.active=book=>!!book&&!book.paused&&!(book.guide&&book.archived)&&(!book.archived||H.state.config.oldReview);
 // 积压：待完成最多保留 3 次，引导的示例考察、掌握档位低、与目标相关程度高的优先，其余顺延
 const PRIORITY={high:0,mid:1,low:2};
 H.due=()=>H.state.tasks.filter(t=>t.status==='pending'&&H.active(H.book(t.book))).sort((x,y)=>(y.demo?1:0)-(x.demo?1:0)||x.mastery-y.mastery||(PRIORITY[x.relevance]??1)-(PRIORITY[y.relevance]??1));
 H.pending=()=>H.due().slice(0,3);
 H.deferred=()=>H.due().slice(3);
 H.scheduled=()=>H.state.tasks.filter(t=>t.status==='scheduled'&&H.active(H.book(t.book)));
 H.kinds={book:{name:'书',formats:'PDF / EPUB'},article:{name:'文章',formats:'网页 / 正文'}};
 H.slot=kind=>H.state.books.find(x=>x.kind===kind&&x.status==='reading'&&!x.guide);
 // 章节状态：已读、跳过各自记录；全部章节已读或跳过才能全书读完
 H.chapterKey=(book,i)=>`${book.id}:${i}`;
 H.isRead=(book,i)=>H.state.completed.includes(H.chapterKey(book,i));
 H.isSkipped=(book,i)=>H.state.skipped.includes(H.chapterKey(book,i));
 H.chapterState=(book,i)=>H.isSkipped(book,i)?'跳过':H.isRead(book,i)?'已读':'';
 H.relNames={high:'与目标高度相关',mid:'与目标有关',low:'与目标关系不大'};
 H.relTag=t=>t.relevance?`<span class="tag rel-${t.relevance}">${H.relNames[t.relevance]}</span>`:'';
 H.ended=book=>book.status==='done'?'读完':'未读完';
 H.goalLines=goal=>`<dl class="goal-lines"><div><dt>想得到什么</dt><dd>${e(goal.gain||'未填写')}</dd></div><div><dt>想学会哪些内容</dt><dd>${e(goal.learn||'未填写')}</dd></div></dl>`;
 H.source=t=>`${H.book(t.book).title} · ${H.book(t.book).sections[t.section].title}`;
 const attrs=id=>`data-id="${e(id)}"`;
 H.bars=n=>`<div class="mastery-bars" aria-label="掌握程度 ${n}，${HouData.levels[n-1]}">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'filled':''}"></i>`).join('')}</div>`;
 H.head=(eyebrow,title,description,action='')=>`<div class="page-head"><div class="od-field"><span class="eyebrow">${e(eyebrow)}</span><h1 tabindex="-1">${e(title)}</h1>${description?`<p>${e(description)}</p>`:''}</div>${action}</div>`;
 H.end=()=>`<footer class="page-end"><span class="od-row">${icon('info')}项目文档作为阅读示例 · 本地交互</span><span>理解，按自己的节奏生长。</span></footer>`;
 H.empty=(title,description,button='')=>`<div class="empty">${icon('library')}<h2>${e(title)}</h2><p>${e(description)}</p>${button}</div>`;
 H.row=t=>`<div class="pending-row"><span class="row-index">${String(H.pending().indexOf(t)+1).padStart(2,'0')}</span><div class="od-fill od-field"><button class="pending-title" type="button" data-action="start" ${attrs(t.id)}>${e(t.title)}</button><span class="pending-source">${e(H.source(t))}</span></div><span class="row-duration">约 ${t.minutes} 分钟</span>${b(icon('chevron'),'start','icon-button',`${attrs(t.id)} aria-label="开始考察：${e(t.title)}"`)}</div>`;
 H.today=()=>{
  const pending=H.pending(), first=pending[0], date=new Date(), day=date.getDate(), weekday=['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][date.getDay()];
  const upcoming=H.scheduled();
  return `<div class="main">${H.head(`${date.getMonth()+1} 月 ${day} 日 · ${weekday}`,'今天，读厚一点。','留几分钟，看看读过的内容理解了多少。',`<div class="calendar-stamp od-stat"><span class="day">${day}</span><span class="month">${String(date.getMonth()+1).padStart(2,'0')} / ${date.getFullYear()}</span></div>`)}
  <section aria-label="待完成的考察"><div class="section-heading"><h2>待完成的考察${pending.length?`<span class="number-tag">${pending.length}</span>`:''}</h2><span class="section-meta">不必一次做完</span></div>${first?`<article class="action-card"><span class="caption"><span class="status-dot"></span>现在可以做的一件事<span>·</span>约 ${first.minutes} 分钟</span><h2>把理解，放进一个新情境。</h2><p>${e(first.description)}</p><div class="source-line">${icon('library')}<span>${e(H.source(first))}</span></div><div class="action-footer">${b(`开始考察 ${icon('up')}`,'start','primary',attrs(first.id))}${b('稍后再做','delay','text-button',attrs(first.id))}<span class="action-index">${first.level} · ${String(1).padStart(2,'0')} / ${String(pending.length).padStart(2,'0')}</span></div></article>${pending.slice(1).map(H.row).join('')}${H.deferred().length?`<p class="caption deferred-note">另有 ${H.deferred().length} 次考察已顺延，做完这几次会依次补上。</p>`:''}`:H.empty('现在没有待完成的考察',upcoming.length?'下一次考察已安排好。也可以主动领取一项。':'读完一个章节，理解就有了下一次生长的起点。',b(upcoming.length?'主动领取':'去阅读',upcoming.length?'claim':'library','primary'))}</section>
  <section class="below" aria-label="在读"><div class="section-heading"><h2>手上在读</h2><span class="section-meta">一本书，一篇文章</span></div><div class="reading-slots">${['book','article'].map(H.slotCard).join('')}</div>${H.state.books.filter(x=>x.guide&&!x.archived).map(g=>`<div class="guide-row od-row spaced"><span><span class="caption">引导 · 不占名额</span> ${e(g.title)}</span>${b('继续读 '+icon('arrow'),'read','inline-link',attrs(g.id))}</div>`).join('')}</section>
  <section class="below"><div class="section-heading"><h2>接下来的安排</h2>${b('查看安排 '+icon('arrow'),'schedule','text-button')}</div>${upcoming.length?`<div class="schedule">${upcoming.slice(0,2).map(t=>`<div class="schedule-item"><div class="schedule-time od-row">${icon('clock')}${e(t.when)}</div><h3>${e(t.title)}</h3><div class="caption">${e(H.book(t.book).title)} · ${t.level} · ${t.minutes} 分钟</div>${b('为什么安排在这时？','reason','',attrs(t.id))}</div>`).join('')}</div>`:`<div class="notice">完成一次考察后，这里会出现接下来的安排。</div>`}</section>
  <section class="below"><div class="section-heading"><h2>理解正在生长</h2><span class="section-meta">按内容查看</span></div><div class="mastery-list">${H.state.books.filter(x=>x.status==='reading'||(x.archived&&H.active(x)&&H.state.tasks.some(t=>t.book===x.id))).slice(0,3).map(book=>{const tasks=H.state.tasks.filter(t=>t.book===book.id&&t.status!=='excluded'),related=tasks.filter(t=>t.relevance==='high').length;const n=tasks.length?Math.round(tasks.reduce((s,t)=>s+t.mastery,0)/tasks.length):0;return `<div class="mastery-row"><div class="od-fill od-field">${b(e(book.title),'book-detail','pending-title',attrs(book.id))}<span class="caption">${book.archived?`已归档 · ${H.ended(book)} · `:''}${tasks.length} 个知识点${related?`，${related} 个与目标高度相关`:''}${book.paused?' · 考察已暂停':''}</span></div>${n?H.bars(n):''}<span class="mastery-level">${n?HouData.levels[n-1]:'待考察'}</span></div>`}).join('')}</div></section>${H.end()}</div>`;
 };
 // 在读位置：每种读物一个；空着时引导导入
 H.slotCard=kind=>{
  const book=H.slot(kind),k=H.kinds[kind];
  if(!book)return `<article class="slot-card empty-slot"><span class="caption">${k.name} · 空着</span><h3>读完了，可以开始下一${kind==='book'?'本':'篇'}。</h3><p class="caption">${k.formats}</p>${b(icon('plus')+`导入一${kind==='book'?'本书':'篇文章'}`,'import-kind','secondary',`data-value="${kind}"`)}</article>`;
  return `<article class="slot-card"><span class="caption">${k.name} · 第 ${book.chapter+1} / ${book.sections.length} 章</span><h3>${b(e(book.title),'read','pending-title',attrs(book.id))}</h3>${book.goal?`<p class="slot-goal"><span class="caption">想学会</span>${e(book.goal.learn||book.goal.gain)}</p>`:`<p class="slot-goal muted">还没写阅读目标。</p>${b('写下阅读目标','goal','inline-link',attrs(book.id))}`}<div class="slot-track" aria-hidden="true"><span style="width:${((book.chapter+1)/book.sections.length)*100}%"></span></div></article>`;
 };
 H.library=()=>{
  const archived=H.state.filter==='archived',books=H.state.books.filter(x=>x.archived===archived);
  const quota=['book','article'].map(k=>`${H.kinds[k].name} ${H.slot(k)?1:0} / 1`).join(' · ');
  return `<div class="main">${H.head('阅读与理解','内容库','手上的读完，再开始下一本。',b(icon('plus')+'导入内容','import','primary'))}<div class="library-toolbar"><div class="tabs" role="tablist" aria-label="内容状态">${['active','archived'].map((v,i)=>b(['在读','归档'][i],'filter','',`data-value="${v}" role="tab" aria-selected="${H.state.filter===v}" tabindex="${H.state.filter===v?0:-1}"`)).join('')}</div><span class="caption">${archived?`${books.length} 份内容 · 不限数量`:`在读名额 · ${quota}`}</span></div>${books.length?books.map(book=>`<article class="library-row"><div class="document-symbol">${icon('doc')}</div><div class="od-fill"><h2>${b(e(book.title),'read','pending-title',attrs(book.id))}</h2><p>${e(archived&&book.status==='abandoned'?'放弃理由：'+book.abandonReason:archived&&book.reflection?'读薄：'+book.reflection:book.description)}</p><div class="library-meta"><span>${H.kinds[book.kind].name}</span><span>${book.sections.length} 个章节</span>${archived?`<span>${H.ended(book)} · ${e(book.endedAt)}</span><span>${H.active(book)?'知识点继续复习':'不再出题'}</span>`:`<span>${book.goal?'已写阅读目标':'还没写阅读目标'}</span><span>${book.paused?'考察已暂停':'阅读位置已记住'}</span>`}</div></div><div class="row-actions">${archived?b(icon('more'),'book-menu','icon-button',`${attrs(book.id)} aria-label="管理${e(book.title)}"`):b(icon('more'),'book-menu','icon-button',`${attrs(book.id)} aria-label="管理${e(book.title)}"`)}</div></article>`).join(''):H.empty(archived?'还没有归档的内容':'手上没有在读的内容',archived?'读完或放弃的内容会归档在这里，不占名额。':'导入一本书或一篇文章，导入后就开始读。',archived?'':b('导入内容','import','secondary'))}${H.end()}</div>`;
 };
 // 把段落文字按区间切开，高亮部分包成 mark。区间互不重叠
 H.paint=(text,ranges)=>{
  let html='',at=0;
  ranges.slice().sort((x,y)=>x.start-y.start).forEach(r=>{if(r.start<at)return;html+=e(text.slice(at,r.start))+`<mark class="${r.cls}"${r.id?` data-mark="${e(r.id)}"`:''}${r.ask?` data-ask="${e(r.ask)}"`:''}>${e(text.slice(r.start,r.end))}</mark>`;at=r.end});
  return html+e(text.slice(at));
 };
 const seltool=t=>{
  if(!t)return '';
  const items=t.mode==='mark'?[['取消高亮','sel-unmark','close'],[t.note?'查看批注':'批注','sel-note','note'],['问 AI','sel-ask','info'],['复制','sel-copy','doc']]:[['高亮','sel-highlight','mark'],['批注','sel-note','note'],['问 AI','sel-ask','info'],['复制','sel-copy','doc']];
  return `<div class="sel-toolbar" id="sel-toolbar" role="toolbar" aria-label="划词工具" style="top:${t.top}px;left:${t.left}px">${items.map(([label,action,ic])=>b(icon(ic)+`<span>${label}</span>`,action,'')).join('')}</div>`;
 };
 const askPanel=book=>{
  const a=H.state.ask;if(!a||a.bookId!==book.id)return '';
  const presets=['解释这段','举个例子',...(book.goal?['和我的阅读目标有什么关系']:[])];
  return `<aside class="ask-panel" aria-label="问 AI"><div class="od-row spaced"><h2>问 AI</h2>${b(icon('close'),'ask-close','icon-button','aria-label="关闭问答"')}</div><blockquote class="ask-quote">${e(a.quote)}</blockquote><div class="ask-log" id="ask-log">${a.messages.map((m,i)=>m.role==='user'?`<p class="ask-q">${e(m.text)}</p>`:`<div class="ask-a"><p>${e(m.text)}</p><div class="od-row spaced"><span class="caption">本地示例回答 · 未连接模型</span>${m.saved?'<span class="caption">已存为批注</span>':b('存为批注','ask-save','inline-link',`data-index="${i}"`)}</div></div>`).join('')}${a.loading?'<div class="loading-line" aria-label="正在回答"></div>':''}</div><div class="ask-presets">${presets.map(q=>b(e(q),'ask-preset','tag-button',`data-value="${e(q)}"`)).join('')}</div><div class="form-field"><label class="sr-only" for="ask-input">你的问题</label><textarea id="ask-input" rows="2" placeholder="继续问，回车发送">${e(a.draft||'')}</textarea></div><div class="form-actions">${b('发送 '+icon('arrow'),'ask-send','primary')}</div><p class="footnote">回答以本书原文为依据。原型不发送模型请求。</p></aside>`;
 };
 H.reader=()=>{
  const book=H.book(H.state.bookId),section=book.sections[book.chapter],key=`${book.id}:${book.chapter}`,done=H.state.completed.includes(key),marks=H.state.marks[key]||[],note=H.state.notes[key]||'';
  const allDone=book.sections.every((_,i)=>H.isRead(book,i)||H.isSkipped(book,i)),skipped=H.isSkipped(book,book.chapter);
  const goal=book.goal?`<details class="goal-panel"${H.state.goalOpen?' open':''}><summary><span>阅读目标</span><span class="caption">${e(book.goal.learn||book.goal.gain)}</span></summary>${H.goalLines(book.goal)}${book.archived?'':b('修改目标','goal','inline-link',attrs(book.id))}</details>`:book.archived?'':`<div class="goal-panel goal-missing od-row spaced"><span class="caption">还没写阅读目标。写下来，知识点会按目标排序。</span>${b('写下阅读目标','goal','inline-link',attrs(book.id))}</div>`;
  const bottom=book.archived?`<span class="caption">已归档 · ${H.ended(book)} · 只能回看</span>${book.status==='done'?b('查看回顾 '+icon('arrow'),'review','secondary',attrs(book.id)):''}`:allDone?`<span class="caption">全部 ${book.sections.length} 章都已读或跳过</span>${book.guide||skipped?'':b('再次提取','extract-start','text-button')}${b(book.guide?'读完引导 '+icon('check'):'全书读完 '+icon('check'),book.guide?'finish-guide':'finish-confirm','primary',attrs(book.id))}`:skipped?`<span class="caption">本章已跳过，不提取、不考察</span>${b('取消跳过','skip-chapter','secondary')}`:`<span class="caption">${done?'本章已读':`第 ${book.chapter+1} / ${book.sections.length} 章 · 阅读位置自动保留`}</span>${done?'':b('跳过本章','skip-chapter','text-button')}${b((done?(book.guide?'已读':'再次提取'):'标记读完')+' '+icon('check'),'extract-start','primary',done&&book.guide?'disabled':'')}`;
  const chapterAsks=(H.state.asks[key]||[]).filter(a=>a.messages.length);const chapterMarks=marks.map(m=>({...m,quote:section.text[m.p].slice(m.start,m.end)}));
  const pending=H.state.ask?.bookId===book.id&&H.state.ask.key===key?H.state.ask.segments:H.state.selTool?.mode==='new'?H.state.selTool.segments:[];
  const paragraph=(text,i)=>{const own=marks.filter(m=>m.p===i).map(m=>({start:m.start,end:m.end,id:m.id,cls:`hl${m.note?' has-note':''}`}));const extra=pending.filter(g=>g.p===i&&!own.some(m=>g.start<m.end&&m.start<g.end)).map(g=>({start:g.start,end:g.end,cls:'hl-pending'}));const taken=[...own,...extra];const asked=(H.state.asks[key]||[]).filter(a=>a.messages.length).flatMap(a=>a.segments.filter(g=>g.p===i).map(g=>({start:g.start,end:g.end,cls:'asked',ask:a.id}))).filter(g=>!taken.some(m=>g.start<m.end&&m.start<g.end)).filter((g,j,all)=>!all.slice(0,j).some(m=>g.start<m.end&&m.start<g.end));return H.paint(text,[...taken,...asked])};
  return `<div class="reader-wrap${H.state.ask?.bookId===book.id?' with-ask':''}"><aside class="toc" aria-label="章节目录"><div class="toc-title">目录 · ${book.sections.length} 章</div>${book.sections.map((s,i)=>b(`<span class="muted">${String(i+1).padStart(2,'0')}</span><span class="od-fill">${e(s.title)}</span>${H.chapterState(book,i)?`<span class="toc-state${H.isSkipped(book,i)?' skipped':''}">${H.chapterState(book,i)}</span>`:''}`,'chapter','',`data-index="${i}" aria-current="${book.chapter===i}"`)).join('')}<div class="caption">${e(book.author)}<br>正文来自项目原始文档</div></aside><article class="reader-content"><div class="reader-meta">${e(book.title)} / 第 ${book.chapter+1} 章</div><h1 tabindex="-1">${e(section.title)}</h1>${H.state.sourceReturn?`<div class="source-banner od-row spaced"><span>正在查看本次考察的原文出处</span>${b('返回结果','return-result','inline-link')}</div>`:''}${goal}<div class="reader-text" id="reader-text">${section.text.map((p,i)=>`<p data-paragraph="${i}" class="${H.state.sourceReturn&&i===0?'source-target':''}">${paragraph(p,i)}</p>`).join('')}</div>${seltool(H.state.selTool)}<div class="reader-tools">${b(icon('note')+(note?'查看本章批注':'写本章批注'),'annotation','text-button')}<span class="caption od-row">选中文字，可以高亮、批注或问 AI</span></div>${note?`<div class="annotation"><div class="caption">本章批注</div><p>${e(note)}</p></div>`:''}${chapterMarks.length||chapterAsks.length?`<section class="mark-list" aria-label="本章划线"><div class="caption">本章划线 · ${chapterMarks.length+chapterAsks.length}</div>${chapterAsks.map(a=>`<div class="mark-item asked-item">${b(e(a.quote),'open-ask','mark-quote',`data-id="${e(a.id)}"`)}<p>问过 · ${a.messages.filter(m=>m.role==='user').length} 个问题，点开可继续追问</p></div>`).join('')}${chapterMarks.sort((x,y)=>x.p-y.p||x.start-y.start).map(m=>`<div class="mark-item">${b(e(m.quote),'goto-mark','mark-quote',`data-id="${e(m.id)}"`)}${m.note?`<p>${e(m.note)}</p>`:''}</div>`).join('')}</section>`:''}<div class="reader-bottom">${bottom}</div></article>${askPanel(book)}</div>`;
 };
 H.extract=()=>{
  const x=H.state.extraction,book=H.book(x.book),section=book.sections[x.section];
  return `<div class="main">${H.head('阅读之后','留下值得理解的知识。',`${book.title} · ${section.title}`)}<div class="notice">${x.loading?'正在整理本地示例知识点。真实提取需要配置模型服务。':x.more?`再次提取只补充没有覆盖到的新知识点，已有的 ${x.kept} 个知识点和考察记录不变。本地示例不会找到新的知识点；${x.points.length?'下面是之前移除的，可以恢复。':'之前也没有移除过知识点。'}`:book.goal?'以下为本地示例提取，已按与阅读目标的相关程度排序。相关程度可以修改；可以移除不想考察的知识点，其余会保留。':'以下为本地示例提取。可以移除不想考察的知识点，其余会保留。写下阅读目标后，知识点会按目标排序。'}</div>${x.loading?`<div class="loading-state"><h2>正在整理知识点…</h2><div class="loading-line"></div><p class="muted">原文位置会与知识点一起保留。</p></div>`:`<div class="extraction-list">${x.points.map((p,i)=>`<article class="knowledge-card ${p.removed?'removed':''}"><div class="od-row spaced"><h3>${e(p.title)}</h3>${b(p.removed?'恢复':icon('close'),'toggle-point','icon-button',`data-index="${i}" aria-label="${p.removed?'恢复':'移除'}知识点：${e(p.title)}"`)}</div>${p.removed?`<p>已移除，不会加入考察。</p>`:`<p>${e(p.text)}</p><div class="caption od-row">原文出处 · ${e(section.title)}${(p.sources||[]).map(x=>`<span class="tag">${x}</span>`).join('')}</div>${p.relevance?`<div class="relevance-row"><div class="od-field"><span class="caption">${e(p.relevanceReason)}</span></div><div class="rel-picker" role="group" aria-label="与目标的相关程度：${e(p.title)}">${['high','mid','low'].map(v=>b(['高','中','低'][['high','mid','low'].indexOf(v)],'set-relevance','',`data-index="${i}" data-value="${v}" aria-pressed="${p.relevance===v}"`)).join('')}</div></div>`:''}`}</article>`).join('')}</div><div class="form-actions">${b('返回阅读','reader','text-button')}${b(`保留 ${x.points.filter(p=>!p.removed).length} 个并加入计划`,'confirm-extraction','primary')}</div>`}</div>`;
 };
 H.qtypes={choice:'情境选择',judge:'判断并说明理由',explain:'用自己的话解释',apply:'情境应用'};
 H.auto=q=>q.type==='choice'||q.type==='judge';
 H.choicesOf=q=>q.type==='judge'?['这个说法对','这个说法不对']:q.choices;
 H.qTitle=q=>q.type==='judge'?`判断这个说法：${q.statement}`:q.question||q.prompt;
 H.game=()=>{
  const g=H.state.game,t=H.state.tasks.find(x=>x.id===g.taskId),q=g.questions[g.step],ro=g.readonly,answered=g.answers[g.step]!==undefined;
  const shell=inner=>`<div class="assessment-shell"><header class="assessment-top"><div class="od-field"><span class="serif">厚 / 考察</span><span class="caption">${e(t.title)} · 本地示例</span></div>${b(icon('close')+'稍后再做','exit-game','text-button')}</header>${inner}</div>`;
  if(g.phase==='loading')return shell(`<div class="loading-state"><div class="eyebrow">为一次理解，准备几道题</div><h1 tabindex="-1">正在准备考察…</h1><div class="loading-line"></div><p class="muted">正在载入本地示例，未向模型发送请求。</p><span class="caption">${e(H.source(t))}</span></div>`);
  if(g.phase==='error')return shell(H.empty('暂时无法开始',g.error+' 本次不计入掌握程度。',b('重新准备','retry-game','primary')));
  const head=`<div class="eyebrow">${ro?'历史考察 · 只读':`第 ${g.step+1} / ${g.questions.length} 题`} · ${H.qtypes[q.type]}</div>`;
  const body=H.auto(q)
   ?`<h1 tabindex="-1">${e(H.qTitle(q))}</h1><p class="assessment-intro">${ro?'查看当时的作答，不产生新的判断。':q.type==='judge'?'先判断对错，再写一句理由。':'选出你认为最合适的做法。'}</p><div class="game-options${q.type==='judge'?' two':''}" role="radiogroup" aria-label="你的选择">${H.choicesOf(q).map((c,i)=>b(`<span class="choice-check">${g.answers[g.step]===i?icon('check'):String.fromCharCode(65+i)}</span><span>${e(c)}</span>`,'choose','game-choice',`data-index="${i}" role="radio" aria-checked="${g.answers[g.step]===i}" tabindex="${g.answers[g.step]===i||(!answered&&i===0)?0:-1}" ${ro?'disabled':''}`)).join('')}</div><div class="form-field"><label for="explanation">${q.type==='judge'?'你的理由':'你的理由（选填）'}</label><textarea id="explanation" rows="3" placeholder="${q.type==='judge'?'为什么对，或者为什么不对？':'为什么选这个？'}" ${ro?'readonly':''}>${e(g.notes[g.step]||'')}</textarea><span class="caption">${q.type==='judge'?'对错在本地按标准答案核对；理由连接模型后按评分细则判分。':'所选做法在本地按标准答案核对；理由不评分。'}</span></div>`
   :`${q.scenario?`<div class="scenario"><span class="caption">情境</span><p>${e(q.scenario)}</p></div>`:''}<h1 tabindex="-1">${e(q.prompt)}</h1><p class="assessment-intro">${ro?'查看当时的作答。':q.type==='explain'?'不看原文，用一两句话说清楚。':'写出你会怎么做，以及为什么。'}</p><div class="form-field"><label for="explanation">你的回答</label><textarea id="explanation" rows="5" placeholder="${q.type==='explain'?'用自己的话说……':'我会……因为……'}" ${ro?'readonly':''}>${e(g.answers[g.step]||'')}</textarea><span class="caption">连接模型后按评分细则判分；原型只保存作答。</span></div>`;
  const blocked=H.auto(q)&&!answered&&!ro;
  return shell(`${head}<div class="question">${body}</div><p id="answer-error" class="field-error" role="alert" ${g.error?'':'hidden'}>${e(g.error||'')}</p><div class="step-track" aria-hidden="true">${g.questions.map((_,i)=>`<i class="${i<=g.step?'active':''}"></i>`).join('')}</div><div class="game-bottom"><span class="caption">${e(H.source(t))}</span>${g.step?b('上一题','game-prev','text-button'):''}${blocked?'<span class="caption choice-hint" id="choice-hint">先选一个，才能继续</span>':''}${b(g.step===g.questions.length-1?(ro?'返回记录':'提交作答'):'下一题','game-next','primary',blocked?'disabled aria-describedby="choice-hint"':'')}</div>`);
 };
 // 结果页：提交后立即打开，选择题和判断题的对错先显示；掌握程度、误解和下次安排在判断完成后补上
 H.finalLevel=r=>r.reviewLevel??r.level;
 H.result=()=>{
  const record=H.state.records.find(x=>x.id===H.state.recordId),t=H.state.tasks.find(x=>x.id===record.taskId),judging=record.judging,reviewing=record.reviewing;
  const qs=record.questions.map(q=>({type:'choice',...q})),autoQs=qs.filter(H.auto),correct=qs.filter((q,i)=>H.auto(q)&&record.answers[i]===q.correct).length;
  const level=H.finalLevel(record);
  const label=judging?'正在判断':reviewing?'正在复核':record.reviewLevel!==undefined?'复核后的结论':level>=3?'理解到位':correct===autoQs.length?'部分掌握':'存在误解';
  const detail=(q,i)=>{
   const a=record.answers[i];
   if(H.auto(q)){const ok=a===q.correct,choices=H.choicesOf(q);return `<section class="result-details"><div class="od-row spaced"><h3>第 ${i+1} 题 · ${H.qtypes[q.type]} · ${ok?'符合原文':'需要再想一想'}</h3>${icon(ok?'check':'info')}</div><p class="muted">${e(H.qTitle(q))}</p><p>${e(q.explanation)}</p><div class="answer-comparison"><div class="od-field"><span class="caption">你的选择</span><p>${e(choices[a])}</p></div><div class="od-field"><span class="caption">原文支持的选择</span><p>${e(choices[q.correct])}</p></div></div>${record.notes[i]?`<p class="footnote">你的理由：${e(record.notes[i])}</p>`:''}</section>`}
   const passed=record.subjective?.[i],verdict=judging?'正在判断':passed?'示例判断：要点到位':'示例判断：还缺要点';
   return `<section class="result-details"><div class="od-row spaced"><h3>第 ${i+1} 题 · ${H.qtypes[q.type]} · ${verdict}</h3>${icon(judging?'clock':passed?'check':'info')}</div><p class="muted">${e(q.prompt)}</p><div class="answer-comparison"><div class="od-field"><span class="caption">你的回答</span><p>${e(a)}</p></div><div class="od-field"><span class="caption">参考答案</span><p>${e(q.reference)}</p></div></div><div class="rubric"><span class="caption">评分细则</span><ul>${q.rubric.map(r=>`<li>${e(r)}</li>`).join('')}</ul></div></section>`;
  };
  const busy=judging||reviewing;
  const levelLine=busy?`<div class="judging"><span class="caption">${judging?'正在综合本次与历次作答判断掌握程度':'正在结合你的理由复核'}</span><div class="loading-line"></div></div>`:`<div class="od-row gap-16">${H.bars(level)}<span>${HouData.levels[level-1]}</span></div><p class="footnote">${e(record.reviewLevel!==undefined?record.reviewReason:record.reason)}</p>`;
  const nextLine=busy?'<p class="muted">判断完成后给出下一次的安排。</p>':`<p>${e(record.next)} · 约 ${t.minutes} 分钟</p><p>${e(record.planReason)}</p>`;
  const disputeNote=record.dispute?`<div class="notice">你的异议：${e(record.dispute)}${record.reviewLevel!==undefined?`<br>复核结果：${HouData.levels[record.reviewLevel-1]}（原判断：${HouData.levels[record.level-1]}），以复核结果为准。`:''}</div>`:'';
  return `<div class="assessment-shell"><header class="assessment-top"><span class="serif">厚 / 理解反馈</span>${b('返回今天 '+icon('close'),'today','text-button')}</header><div class="eyebrow">本次考察已完成 · 示例反馈</div><h1 tabindex="-1">理解，从这里再深一点。</h1><div class="result-card"><div class="result-label">${icon(busy?'clock':level>=3||correct===autoQs.length?'check':'info')}<span>${label}</span></div><h2>${e(t.title)}</h2><p class="caption">本地核对：${correct} / ${autoQs.length} 道选择与判断符合原文</p>${levelLine}</div>${qs.map(detail).join('')}<section class="result-details"><h3>回到原文</h3><p>${e(H.book(t.book).sections[t.section].text[0])}</p>${b(e(H.source(t))+' '+icon('up'),'source','inline-link',attrs(t.id))}</section><section class="result-details"><h3>接下来，再换一个角度。</h3>${nextLine}</section>${disputeNote}<div class="game-bottom">${busy?'':b(record.dispute?'查看复核记录':'对结果有异议','dispute','text-button')}${b('回到今天 '+icon('arrow'),'today','primary')}</div><p class="footnote">判断与复核为本地示例规则，不代表模型已运行。可以直接关掉，判断会在后台完成。</p></div>`;
 };
 // 首次使用：欢迎页，两步——配置模型服务（可跳过）、开始读引导
 H.welcome=()=>{
  const chat=H.provider(H.state.config.chat),configured=!!chat,skipped=H.state.configSkipped;
  return `<div class="welcome"><img class="welcome-mark" src="../brand/icon/hou-icon-master${H.state.theme==='dark'?'-dark':''}.png" width="1024" height="1024" alt="厚应用图标"><div class="eyebrow">第一次打开《厚》</div><h1 tabindex="-1">读厚，再读薄。</h1><p class="welcome-lead">每读完一章，留下几个值得理解的知识点；在合适的时刻，花几分钟考察一次理解。读完一本，再用几句话写下自己的所得。</p>
  <ol class="welcome-steps"><li class="welcome-step${configured||skipped?' done':''}"><span class="step-no">${configured||skipped?icon('check'):'1'}</span><div class="od-fill"><h2>配置模型服务</h2><p class="muted">提取知识点、出题和判分需要模型。${configured?`已配置：${e(chat.name)} · ${e(chat.model)}`:skipped?'已跳过，之后可以在设置里配置。':'可以先跳过：引导自带知识点和考察题，不需要模型。'}</p>${configured||skipped?'':`<div class="od-row gap-16">${b('去配置','welcome-config','secondary')}${b('先跳过','welcome-skip-config','text-button')}</div>`}</div></li>
  <li class="welcome-step"><span class="step-no">2</span><div class="od-fill"><h2>读一篇引导</h2><p class="muted">《怎样用厚》是你的第一篇在读文章。顺着读下去，会把划词、标记读完、考察、回顾都用一遍，大约十分钟。</p>${b('开始读引导 '+icon('arrow'),'open-guide','primary')}</div></li></ol>
  <p class="footnote">原型示例 · 未连接模型 · 操作仅保留在本次会话</p></div>`;
 };
 // 模型服务：可以添加多个，再为"对话"和"OCR"两种用途各指定一个
 H.providerTypes={anthropic:'Anthropic','openai-compatible':'OpenAI 兼容'};
 H.provider=id=>H.state.providers.find(p=>p.id===id);
 H.providerSection=()=>{
  const list=H.state.providers,c=H.state.config;
  const select=(id,label,purpose,value)=>`<div class="settings-row"><div class="od-field"><label for="${id}">${label}</label><span class="caption">${purpose}</span></div><select id="${id}" class="select"><option value="">未指定</option>${list.map(p=>`<option value="${e(p.id)}"${value===p.id?' selected':''}>${e(p.name)}</option>`).join('')}</select></div>`;
  return `<section class="settings-section"><div class="section-heading"><h2>模型服务</h2><span class="tag">${c.chat?'对话已指定':'未配置'}</span></div><div class="notice">原型不发送模型请求；"测试连接"为模拟结果。密钥只保留在当前页面内存中，刷新后清除。</div>${list.length?list.map(p=>`<div class="settings-row provider-row"><div class="od-field"><span>${e(p.name)}</span><span class="caption">${H.providerTypes[p.type]} · ${e(p.model)} · ${e(p.url)}</span></div><div class="od-row">${p.testing?'<span class="caption">正在测试…</span>':`<span class="tag">${p.tested?'连接正常':'未测试'}</span>`}${b('测试连接','test-provider','secondary',`data-id="${e(p.id)}"`)}${b(icon('close'),'remove-provider','icon-button',`data-id="${e(p.id)}" aria-label="删除 ${e(p.name)}"`)}</div></div>`).join(''):'<p class="muted provider-empty">还没有模型服务。提取知识点、出题、判断和问 AI 需要"对话"服务，导入 PDF 需要"OCR"服务。</p>'}<div class="form-actions">${b(icon('plus')+'添加模型服务','add-provider','secondary')}</div>${select('use-chat','对话','提取知识点、出题、判断、问 AI',c.chat)}${select('use-ocr','OCR','把 PDF 页面转成文字，需要支持图片输入',c.ocr)}</section>`;
 };
 H.settings=()=>`<div class="main">${H.head('按你的节奏','设置','把工具调到适合自己的状态。')}${H.state.configFromWelcome&&H.state.firstRun?`<div class="notice od-row spaced"><span>配置好模型服务后，回到欢迎页继续。</span>${b('回到欢迎页','back-welcome','inline-link')}</div>`:''}${H.providerSection()}<section class="settings-section"><h2>阅读与外观</h2><div class="settings-row"><div class="od-field"><span>外观</span><span class="caption">按当前页面选择浅色或深色</span></div><div class="tabs" role="tablist" aria-label="外观">${['light','dark'].map((v,i)=>b(['浅色','深色'][i],'theme','',`data-value="${v}" role="tab" aria-selected="${H.state.theme===v}" tabindex="${H.state.theme===v?0:-1}"`)).join('')}</div></div><div class="settings-row"><div class="od-field"><span>减少动态效果</span><span class="caption">仅保留状态变化，不使用位移动效</span></div>${b('<span></span>','reduce-motion','switch',`role="switch" aria-label="减少动态效果" aria-checked="${H.state.reduceMotion}"`)}</div><div class="settings-row"><div class="od-field"><span>旧书复习</span><span class="caption">${H.state.config.oldReview?'读完或放弃的内容，已提取的知识点继续按计划出题':'归档内容的知识点不再出题，掌握程度和记录都保留'}</span></div>${b('<span></span>','toggle-old-review','switch',`role="switch" aria-label="旧书复习" aria-checked="${H.state.config.oldReview}"`)}</div></section><section class="settings-section"><h2>送达与后台</h2><div class="settings-row"><div class="od-field"><span>主动领取快捷键</span><span class="caption">原型中仅在本页面生效</span></div>${b(e(H.state.config.shortcut),'shortcut','secondary')}</div><div class="settings-row"><div class="od-field"><span>开机自启</span><span class="caption">开机后只显示菜单栏图标；关闭主窗口时退到菜单栏，继续按时提醒</span></div>${b('<span></span>','toggle-autostart','switch',`role="switch" aria-label="开机自启" aria-checked="${H.state.config.autoStart}"`)}</div><div class="settings-row"><div class="od-field"><span>菜单栏与通知</span><span class="caption">在页面内查看待完成面板和通知样式</span></div>${b('查看通知','notification','secondary')}</div></section><section class="settings-section"><h2>首次使用</h2><div class="settings-row"><div class="od-field"><span>重新打开引导</span><span class="caption">《怎样用厚》是内置文章，不占在读名额</span></div>${b('打开引导','open-guide','secondary')}</div><div class="settings-row"><div class="od-field"><span>从头体验首次使用</span><span class="caption">清空本次会话的数据，回到欢迎页</span></div>${b('从头开始','first-run-confirm','text-button')}</div></section>${H.end()}</div>`;
 H.records=()=>`<div class="main">${H.head('每一步，都有来处','运行记录','保留触发、作答、判断与接下来的安排。')}${H.state.records.length?H.state.records.slice().reverse().map(r=>{const t=H.state.tasks.find(x=>x.id===r.taskId);if(r.deleted||!t)return `<article class="log-row"><div class="log-date od-field"><span>${e(r.date)}</span><span>${e(r.time)}</span></div><div class="od-fill"><h3 class="muted">已删除的读物</h3><p>内容与作答已随读物彻底删除</p></div></article>`;return `<article class="log-row"><div class="log-date od-field"><span>${e(r.date)}</span><span>${e(r.time)}</span></div><div class="od-fill"><h3>${b(e(t.title),'log','pending-title',attrs(r.id))}</h3><p>${e(r.status==='interrupted'?'考察中断 · 未计入掌握程度':(r.judging?'考察完成 · 正在判断':`考察完成 · ${HouData.levels[H.finalLevel(r)-1]}`))}</p><span class="caption">${e(r.trigger)} · 本地示例</span></div><div class="row-actions">${b(icon('chevron'),'log','icon-button',`${attrs(r.id)} aria-label="查看运行记录"`)}</div></article>`}).join(''):H.empty('还没有运行记录','完成一次考察后，触发原因与作答会一起留在这里。',b('回到今天','today','secondary'))}${H.end()}</div>`;
 H.log=()=>{
  const r=H.state.records.find(x=>x.id===H.state.recordId),t=H.state.tasks.find(x=>x.id===r.taskId);
  return `<div class="main">${H.head('运行记录 · 本地示例',t.title,`${r.date} ${r.time} · ${r.trigger}`)}<div class="notice">${r.status==='interrupted'?'考察中途关闭，已回到待完成列表。本次不计入掌握程度。':'本次使用本地预设情境与规则。未调用 LLM，未产生模型输入、输出或组件版本记录。'}</div>${[{label:'知识点与原文',value:{title:t.title,source:H.source(t),passage:H.book(t.book).sections[t.section].text[0]}},{label:'操作过程与作答',value:{operations:r.operations,answers:r.answers,notes:r.notes,status:r.status}},{label:'判断与计划',value:{level:r.level?HouData.levels[r.level-1]:'未判断',reviewResult:r.reviewLevel!==undefined?HouData.levels[r.reviewLevel-1]:null,dispute:r.dispute||null,reviewed:r.reviewed||false,next:r.next||null}}].map(x=>`<details open><summary>${e(x.label)}</summary><pre>${e(JSON.stringify(x.value,null,2))}</pre></details>`).join('')}<div class="form-actions">${b('返回列表','records','text-button')}${r.status==='complete'?b('查看当时的考察','replay','secondary',attrs(r.id)):''}${r.status==='complete'?b('查看结果','record-result','primary',attrs(r.id)):''}</div></div>`;
 };
 H.schedule=()=>`<div class="main">${H.head('理解需要一点间隔','接下来的安排','时间可以调整，节奏由你决定。')}${H.scheduled().length?H.scheduled().map(t=>`<article class="pending-row"><div class="od-fill od-field"><span class="caption">${e(t.when)}</span><h2>${e(t.title)}</h2><span class="caption">${e(H.source(t))}</span><p class="muted">${e(t.reason)}</p></div>${b('延后','delay','secondary',attrs(t.id))}</article>`).join(''):H.empty('暂无接下来的安排','完成一次考察，或读完一个章节后，会出现新的安排。')}${H.end()}</div>`;
 // 对照目标回顾：全书读完时进入，也可以从归档回看
 H.review=()=>{
  const book=H.book(H.state.bookId),tasks=H.state.tasks.filter(t=>t.book===book.id&&t.status!=='excluded');
  const tested=t=>!t.custom||H.state.records.some(r=>r.taskId===t.id&&r.status==='complete');
  const related=book.goal?tasks.filter(t=>t.relevance==='high'):tasks,weak=tasks.filter(t=>tested(t)&&t.mastery<=2),untested=tasks.filter(t=>!tested(t));
  const row=t=>`<article class="pending-row"><div class="od-fill od-field"><h3>${e(t.title)}</h3><span class="caption">${e(book.sections[t.section].title)}</span></div>${tested(t)?H.bars(t.mastery)+`<span class="mastery-level">${HouData.levels[t.mastery-1]}</span>`:'<span class="mastery-level">还没考到</span>'}</article>`;
  return `<div class="main">${H.head(`对照目标回顾 · ${H.ended(book)} · ${book.endedAt}`,book.title,'读厚之后，再读薄。')}
  <section class="goal-summary"><h2>当初的阅读目标</h2>${book.goal?H.goalLines(book.goal):`<p class="muted">这${book.kind==='book'?'本书':'篇文章'}没有写阅读目标，下面汇总全部知识点的掌握程度。</p>`}</section>
  <section class="below"><div class="section-heading"><h2>${book.goal?'与目标高度相关的知识点':'全书知识点'}</h2><span class="section-meta">${related.length} 个</span></div>${related.length?related.map(row).join(''):'<div class="notice">没有与目标高度相关的知识点。可以对照目标，想想这本书是否真的回答了你的问题。</div>'}</section>
  <section class="below"><div class="section-heading"><h2>仍薄弱的地方</h2><span class="section-meta">掌握程度在“能识别”及以下</span></div>${!tasks.some(tested)?'<div class="notice">还没有考过的知识点。</div>':weak.length?weak.map(t=>`<div class="weak-row"><div class="od-fill od-field"><h3>${e(t.title)}</h3><p class="muted">${e(book.sections[t.section].text[0])}</p></div>${b('回到原文 '+icon('up'),'review-source','inline-link',attrs(t.id))}</div>`).join(''):'<div class="notice">考过的知识点都在“能解释”及以上。</div>'}</section>
  ${untested.length?`<section class="below"><div class="section-heading"><h2>书里有，但还没考到</h2><span class="section-meta">${untested.length} 个</span></div>${untested.map(row).join('')}</section>`:''}
  <section class="below"><h2>再读薄</h2><div class="form-field"><label for="reflection">用几句话写下你从这${book.kind==='book'?'本书':'篇文章'}得到的观点</label><textarea id="reflection" placeholder="不复述原文，只写你自己的结论。">${e(book.reflection||'')}</textarea><span class="caption">保存在这${book.kind==='book'?'本书':'篇文章'}下，回顾时可以再看。</span></div><div class="form-actions">${b('回到今天','today','text-button')}${b('保存观点','save-reflection','primary',attrs(book.id))}</div></section>${H.end()}</div>`;
 };
 H.bookDetail=()=>{
  const book=H.book(H.state.bookId),tasks=H.state.tasks.filter(t=>t.book===book.id);
  const status=book.archived?`${H.ended(book)} · ${book.endedAt}${book.status==='abandoned'?` · 放弃理由：${book.abandonReason}`:''}`:book.description;
  const exam=book.archived&&!H.state.config.oldReview?'"旧书复习"已关闭，不再出题':book.paused?'已暂停，阅读与历史记录不受影响':'按计划进行，可以随时暂停';
  return `<div class="main">${H.head(book.archived?'已归档 · 按章节理解':'按章节理解',book.title,status,b((book.archived?'回看':'继续阅读')+' '+icon('arrow'),'read','primary',attrs(book.id)))}${book.goal?`<section class="goal-summary"><div class="od-row spaced"><h2>阅读目标</h2>${book.archived?'':b('修改目标','goal','inline-link',attrs(book.id))}</div>${H.goalLines(book.goal)}</section>`:''}<div class="settings-row"><div class="od-field"><span>这份内容的考察</span><span class="caption">${exam}</span></div>${b(book.paused?'恢复考察':'暂停考察','pause-book','secondary',attrs(book.id))}</div>${tasks.length?tasks.map(t=>`<article class="pending-row"><div class="od-fill od-field"><h3>${e(t.title)}</h3><span class="caption">${e(book.sections[t.section].title)}</span>${H.relTag(t)?`<span>${H.relTag(t)}</span>`:''}<span class="caption">${t.status==='pending'?'待完成':e(t.when||'已安排')}</span></div>${H.bars(t.mastery)}<span class="mastery-level">${HouData.levels[t.mastery-1]}</span></article>`).join(''):H.empty('还没有知识点','读完一个章节，再把值得理解的知识加入计划。')}${H.end()}</div>`;
 };
})();
